commands.text:
param([ValidateSet('whole-build','safety-build','safety-test','reference-test')][string]$Action='whole-build')
$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue';[Console]::OutputEncoding=[Text.UTF8Encoding]::new($false)
if(-not [Environment]::MachineName.Equals('baiying',[StringComparison]::OrdinalIgnoreCase)){throw 'Requires baiying'}
$repo='D:\projects\AIMA-public-hipblaslt-producer-20260913';$seed='D:\projects\AIMA-public-dense-device-replay-20260913'
$sha='584588a8350624acb9edc6559114bc4f9c2f0258';$bundle='D:\projects\hipblaslt-producer-584588a.bundle'
if((Get-FileHash $bundle -Algorithm SHA256).Hash.ToLowerInvariant() -ne '5c4ff9d5a9c3f98e89551bb4bc0fc52c646babfb3af6b94bfee02cc4184a49cb'){throw 'Bundle changed'}
if(-not (Test-Path $repo)){
 & git -C $seed fetch $bundle HEAD;if($LASTEXITCODE -ne 0){throw 'Fetch failed'}
 & git -C $seed worktree add --detach $repo $sha;if($LASTEXITCODE -ne 0){throw 'Worktree creation failed'}
}
if((& git -C $repo rev-parse HEAD).Trim() -ne $sha -or @(& git -C $repo status --porcelain).Count -ne 0){throw 'Source mismatch'}
$buildName=if($Action -eq 'whole-build'){'whole'}else{'safety'}
$build=Join-Path $repo ('build\'+$buildName);$null=New-Item -ItemType Directory -Path $build -Force
$recordDir=Join-Path $repo ('build\hipblaslt-producer-'+$Action+'-r1');$specPath=Join-Path $build ($Action+'-spec-r1.json')
foreach($p in @($recordDir,$specPath)){if(Test-Path $p){throw ('Existing evidence: '+$p)}}
$env:PATH='C:\Program Files\AMD\ROCm\7.1\bin;'+$env:PATH
$env:QRT_QWEN36_PREFILL_HIPBLASLT_PRODUCER='1'
$env:QRT_QWEN36_HAWKEYE_DEVICE_REPLAY='0'
$env:QRT_QWEN36_HAWKEYE_CORRECTION_MAXIMUM_BLOCKS_PER_LAUNCH='4096'
$sourceInputs=@();foreach($name in @('native\providers\whole_provider.cpp','native\providers\hawkeye_dispatch_policy.h','native\providers\moe_accumulator\sm121_subgroup.h','native\providers\moe_accumulator\sm121_prefill_projection.h','native\providers\moe_accumulator\sm121_canonical_normalize.h','native\providers\moe_accumulator\sm121_wave16.h','native\providers\moe_accumulator\sm121_lane_reduce.h','tests\native\hawkeye_device_replay_selftest.h','tests\native\projection_safety_selftest.cpp','scripts\baiying_build_whole_provider.ps1')){$sourceInputs+=@{file=$name;sha256=(Get-FileHash (Join-Path $repo $name) -Algorithm SHA256).Hash.ToLowerInvariant()}}
$spec=[ordered]@{executable='';arguments=@();working_directory=$repo;repo_commit=$sha;command_file=$PSCommandPath;command_file_sha256=(Get-FileHash $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();source_inputs=$sourceInputs;sm121_dpp_reduction=$true;sm121_compact_normalize=$true;hawkeye_replay_lanes=4;prefill_hipblaslt_producer=$true;hawkeye_device_replay=$false;maximum_blocks_per_launch=4096;model='none; native build or original-vs-device-count correction test';model_loaded=$false;inference_acceptance=$false;purpose='Replace the QKV/Z approximate matrix producer with existing hipBLASLt BF16 operands and F32 output, heuristic0. Retain original norm bounds, selector, exact dot, rounding, DPP1 and compact normalization1. Device replay0; all real QKV BF16 endpoints required before complete product testing.'}
if($Action -like '*-build'){
 $spec.executable='C:\Windows\System32\WindowsPowerShell\v1.0\powershell.exe'
 $spec.arguments=@('-NoLogo','-NoProfile','-NonInteractive','-File',(Join-Path $repo 'scripts\baiying_build_whole_provider.ps1'),'-OutDir',$build,'-DppReduction','1','-CompactNormalize','1','-HawkeyeReplayLanes','4','-CompileTimeoutSeconds','180')
 if($Action -eq 'safety-build'){$spec.arguments+=@('-ProjectionSafetyTest')}
 $timeout=210
}else{
 $metaPath=Join-Path $build 'build-provenance.json';$meta=[IO.File]::ReadAllText($metaPath)|ConvertFrom-Json
 $exe=Join-Path $build 'qrt-projection-safety.exe';$artifact=@($meta.artifacts|Where-Object {$_.name -eq 'qrt-projection-safety.exe'})
 if($artifact.Count -ne 1 -or $meta.repo_commit -ne $sha -or (Get-FileHash $exe -Algorithm SHA256).Hash.ToLowerInvariant() -ne $artifact[0].sha256){throw 'Safety executable mismatch'}
 $spec.build_provenance_sha256=(Get-FileHash $metaPath -Algorithm SHA256).Hash.ToLowerInvariant();$spec.executable=$exe;$spec.arguments=@('--small');$timeout=120

 if($Action -eq 'reference-test'){
  $inputTensor='D:\projects\AIMA-public-exact-ab-20260910\build\fla-model-q7169-embeddingnorm-capture-r1\input-rmsnorm-bf16.bin'
  $weightTensor='D:\projects\AIMA-public-capture-20260910\build\layer0-weights-r1\qkv.bin'
  $referenceTensor='D:\projects\sm121-qkv-reference-9510d980.bin'
  $tensors=@(@{path=$inputTensor;sha256='6c67321f81040780088a742070c48ab3023043b8ef9de71d1ed5a970a8fe9161'},@{path=$weightTensor;sha256='b06edcc9973be74f862d072f89a195e2eecea067ee615144be8510656122401f'},@{path=$referenceTensor;sha256='9510d98057e047e7dd6f4e7b9b6010862e54e938d37bb854078c2de419f0bf37'})
  foreach($tensor in $tensors){if((Get-FileHash $tensor.path -Algorithm SHA256).Hash.ToLowerInvariant() -ne $tensor.sha256){throw 'Original QKV tensor mismatch'}}
  $spec.arguments=@('--real-qkv',$inputTensor,$weightTensor,$referenceTensor,'1000')
  $spec.model='D:\models\Qwen3.6-35B-A3B; original captured layer-zero QKV only'
  $spec.model_index_sha256='41b9356101ebf8e7519e150dc811f80c4226e727301fbb032b890f006ed0be83'
  $spec.tensor_inputs=$tensors;$spec.gb10_reference_host='aitopatom-66c4'
  $spec.gb10_capture_sha256='5522ec3e4725adf459e505dff61aa3981a08b416b7b2bfe40e929ccf250b4d8b'
  $spec.prompt_sha256='26515be92b5563d921bade3ed6673ffe9e0c6560fbd7d78f587a0400da802804'
  $spec.reference_is_compute_input=$false;$spec.selector_error_bound_ppb=1000
 }

}
[IO.File]::WriteAllText($specPath,($spec|ConvertTo-Json -Depth 8),[Text.UTF8Encoding]::new($false))
& (Join-Path $repo 'scripts\baiying_guarded_inference.ps1') -SpecPath $specPath -OutDir $recordDir -TimeoutSeconds $timeout|Out-Null
$r=[IO.File]::ReadAllText((Join-Path $recordDir 'run-record.json'))|ConvertFrom-Json
$r|Select-Object reason,exit_code,wall_ms,host_checks|ConvertTo-Json -Depth 5
foreach($name in @('product.stdout.jsonl','product.stderr.log')){Get-Content (Join-Path $recordDir $name) -Tail 8|ForEach-Object {$_.Substring(0,[Math]::Min(800,$_.Length))}}
if($r.reason -ne 'completed' -or $r.exit_code -ne 0 -or -not $r.host_checks_pass){throw 'Native device replay action failed'}

if($Action -in @('safety-test','reference-test')){
 $reports=@([IO.File]::ReadAllLines((Join-Path $recordDir 'product.stdout.jsonl'))|Where-Object {$_.StartsWith('{')}|ForEach-Object {$_|ConvertFrom-Json})
 $markers=@([IO.File]::ReadAllLines((Join-Path $recordDir 'product.stderr.log'))|Where-Object {$_.StartsWith('BATCH_MARK prefill_hipblaslt_producer ')})
 if($Action -eq 'safety-test'){
  $cases=@($reports|Where-Object {$_.type -eq 'projection_case'})
  if($cases.Count -ne 8 -or $markers.Count -ne 8 -or @($cases|Where-Object {$_.bf16_reference_mismatches -ne 0 -or -not $_.redzones_pass}).Count){throw 'Native producer safety boundary failed'}
 }else{
  $cases=@($reports|Where-Object {$_.type -eq 'real_qkv_result'})
  if($cases.Count -ne 1 -or $markers.Count -ne 1 -or $cases[0].bf16_mismatches -ne 0 -or $cases[0].elements -ne 58728448 -or -not $cases[0].redzones_pass -or -not $cases[0].inputs_immutable){throw 'Original QKV boundary failed'}
 }
}
